/* Credit Sprint question bank, part 2. All items are original. Same format as questions.js. */
window.CS_QUESTIONS_RAW = (window.CS_QUESTIONS_RAW || []).concat([
/* ---------- Unit 1 ---------- */
[1,"Scarcity exists because:",["Resources are limited relative to people's wants","Every society faces this, rich or poor."],[["Prices are too high","High prices are a result of scarcity, not its cause."],["Governments regulate markets","Scarcity would exist with no government at all."],["Some people are poor","Even the richest economies face scarcity."]]],
[1,"Which is an example of capital as a factor of production?",["A delivery truck used by a bakery","Capital is a human-made tool used to produce other goods."],[["Money in the bakery's bank account","Money is financial capital, not a factor of production."],["The bakery owner's idea for a new pastry","That's entrepreneurship."],["The wheat used to make bread","That's an input from land (natural resources)."]]],
[1,"Country X shifts production toward capital goods today instead of consumer goods. Compared with a country that doesn't, Country X will most likely:",["Have a PPC that shifts outward more in the future","More capital today means more productive capacity later."],[["Have a PPC that shifts inward","Building capital expands capacity."],["Produce inside its PPC","The choice is a point on the curve, not inside it."],["Have more consumer goods today","It gives up consumer goods today."]]],
[1,"A straight-line production possibilities curve shows:",["Constant opportunity cost","Resources are equally suited to both goods."],[["Increasing opportunity cost","That gives a bowed-out curve."],["Decreasing opportunity cost","That gives a bowed-in curve."],["No opportunity cost","Moving along any PPC requires giving something up."]]],
[1,"Specialization and trade based on comparative advantage allow countries to:",["Consume combinations of goods outside their own PPCs","Trade lets each country consume more than it could make alone."],[["Produce outside their own PPCs","Production stays on the PPC; consumption can go beyond it."],["Avoid all opportunity costs","Opportunity costs still exist."],["Eliminate scarcity","Trade eases scarcity but can't end it."]]],
[1,"On a PPC, moving from 20 to 30 tanks requires cutting food from 50 to 35 units. The opportunity cost of one more tank is:",["1.5 units of food","15 units of food ÷ 10 tanks = 1.5."],[["15 units of food","That's the cost of all 10 tanks."],["0.67 units of food","That's the cost of food in tanks."],["10 units of food","That's the change in tanks."]]],
[1,"More firms enter the market for electric scooters. In that market:",["Supply increases","More sellers shift supply right."],[["Demand increases","The number of sellers affects supply."],["Supply decreases","More sellers mean more supply."],["Quantity supplied rises but supply doesn't change","The curve itself shifts when sellers enter."]]],
[1,"Producers expect the price of their good to rise next month. Today's supply:",["Decreases","Sellers hold back some output to sell later at the higher price."],[["Increases","They'd rather sell later."],["Doesn't change","Expectations shift supply."],["Becomes vertical","Expectations shift supply; they don't change its shape."]]],
[1,"Buyers expect the price of a game console to rise next month. Today's demand:",["Increases","Buyers rush to purchase before the price goes up."],[["Decreases","They'd rather buy now."],["Doesn't change","Expectations shift demand."],["Quantity demanded falls","Today's price hasn't changed."]]],
[1,"Gasoline prices rise sharply. Demand for large SUVs, a complement, will most likely:",["Decrease","Complements are used together, so pricier gas makes SUVs less attractive."],[["Increase","That would be true for a substitute."],["Stay the same","Prices of related goods shift demand."],["Become perfectly elastic","Demand shifts; its elasticity isn't the issue."]]],
[1,"Incomes rise and demand for instant noodles falls. Instant noodles are:",["An inferior good","Demand for an inferior good falls as income rises."],[["A normal good","Demand for a normal good rises with income."],["A complement","Complements relate to other goods' prices, not income."],["A substitute","Substitutes relate to other goods' prices, not income."]]],
[1,"Equilibrium price is the price at which:",["Quantity demanded equals quantity supplied","The market clears with no shortage or surplus."],[["Demand equals supply at every price","Equilibrium is one price, not every price."],["Sellers earn the most profit","Equilibrium isn't defined by profit."],["The government sets a ceiling","Ceilings are government-imposed, not equilibrium."]]],
[1,"The price of a good is above its equilibrium price. What happens?",["A surplus pushes the price down","Sellers cut prices to clear unsold goods."],[["A shortage pushes the price up","Above equilibrium there's a surplus, not a shortage."],["Demand shifts right","Being off equilibrium doesn't shift demand."],["Nothing, the price stays there","Without a price floor, the price falls."]]],
[1,"Supply decreases while demand increases. What happens to equilibrium?",["Price rises; quantity is indeterminate","Both shifts push price up; their effects on quantity conflict."],[["Price falls; quantity rises","Both shifts raise price."],["Quantity rises; price is indeterminate","Price is the certain change."],["Price and quantity both fall","Higher demand pushes quantity up."]]],
[1,"The government gives producers a per-unit subsidy. The supply curve:",["Shifts right","The subsidy lowers producers' costs."],[["Shifts left","That's what a tax does."],["Doesn't move","Cost changes shift supply."],["Becomes vertical","A subsidy shifts supply; it doesn't make it vertical."]]],
[1,"The law of supply says that, all else equal:",["A higher price leads to a greater quantity supplied","Higher prices make production more profitable."],[["A higher price shifts supply right","Price changes move along the curve."],["Supply always equals demand","That's only true at equilibrium."],["A higher price reduces quantity supplied","That reverses the law."]]],
[1,"The price of steel, an input for cars, falls. In the car market:",["Supply increases","Lower input costs shift supply right."],[["Demand increases","Input costs affect sellers."],["Supply decreases","Cheaper inputs increase supply."],["Quantity demanded falls","Buyers aren't directly affected by input costs."]]],
[1,"In a command economy, the key decisions about what to produce are made by:",["The government","Central planners decide production and allocation."],[["Consumers and firms in markets","That's a market economy."],["Custom and tradition","That's a traditional economy."],["Foreign trade partners","No economy lets other countries decide its output."]]],
[1,"Which question is macroeconomic?",["Why did the national inflation rate rise this year?","Macroeconomics studies the economy as a whole."],[["Why did the price of avocados rise?","That's one market: microeconomics."],["How does a firm choose how many workers to hire?","That's a single firm: microeconomics."],["Why do consumers buy less of a good when its price rises?","That's individual demand: microeconomics."]]],
[1,"Economists use the phrase \"ceteris paribus\" to mean:",["All other things held constant","It isolates the effect of one variable."],[["Prices are fixed","It means holding other factors constant, not just prices."],["The market is in equilibrium","It's about holding factors constant, not equilibrium."],["The long run","It isn't a time period."]]],
[1,"For a student who leaves a $30,000 job to attend college, the opportunity cost of a year of school includes:",["Tuition plus the $30,000 in forgone wages","Both are given up by choosing school."],[["Only the tuition","Forgone wages are a real cost."],["Food the student would eat anyway","Costs paid either way aren't opportunity costs of school."],["Money spent on last year's textbooks","That's a sunk cost."]]],
[1,"The government places a per-unit tax on cigarette producers. In the cigarette market:",["Supply decreases and price rises","The tax raises costs, shifting supply left."],[["Demand decreases and price falls","A tax on producers shifts supply."],["Supply increases and price falls","Taxes raise costs; they don't increase supply."],["Nothing changes","Taxes on sellers shift supply."]]],
[1,"In France, 1 bottle of wine costs 2 wheels of cheese in opportunity cost. In Italy, it costs 1 wheel. Which country should specialize in wine?",["Italy","Italy gives up less cheese per bottle of wine."],[["France","France's opportunity cost of wine is higher."],["Both countries equally","Different opportunity costs mean one should specialize."],["Neither, since opportunity costs aren't equal","Unequal opportunity costs are exactly what create gains from trade."]]],
[1,"Gains from trade come mainly from:",["Specializing by comparative advantage, which raises total output","Each country produces what it gives up least to make."],[["Exporting more than you import","Gains come from specialization, not a trade surplus."],["Absolute advantage alone","Trade benefits both sides even without absolute advantage."],["Higher tariffs","Tariffs reduce gains from trade."]]],
[1,"A price ceiling set above the equilibrium price will:",["Have no effect on the market","The market price is already below the ceiling, so it doesn't bind."],[["Create a shortage","Only a ceiling below equilibrium creates a shortage."],["Create a surplus","Surpluses come from binding price floors."],["Raise the market price to the ceiling","The price stays at equilibrium."]]],

/* ---------- Unit 2 ---------- */
[2,"Why does GDP measured by total spending equal GDP measured by total income?",["Every dollar spent on final output is income to someone","Spending by buyers is earned by sellers and workers."],[["The government requires them to match","It's an accounting identity, not a law."],["Both exclude all imports","Imports are subtracted on the spending side only to remove foreign output."],["They measure different things that happen to be equal","They measure the same output from two sides."]]],
[2,"A firm produces goods this year but doesn't sell them by December 31. In GDP, they are:",["Counted as investment (inventory)","Unsold output this year is added to inventories."],[["Not counted until sold","They're counted when produced, as inventory."],["Counted as consumption","No consumer has bought them yet."],["Counted as government purchases","The government didn't buy them."]]],
[2,"A farmer sells wheat to a miller for $1. The miller sells flour to a baker for $3. The baker sells bread to a consumer for $5. How much does this add to GDP?",["$5","Only the final good counts; it equals the sum of value added."],[["$9","That double counts intermediate goods."],["$3","That's only the miller's sale."],["$1","That's only the first stage."]]],
[2,"GDP per capita is calculated as:",["GDP ÷ population","It measures output per person."],[["GDP ÷ labor force","That's closer to output per worker."],["GDP × population","That isn't a meaningful measure."],["Nominal GDP ÷ real GDP","That's a price index, divided by 100."]]],
[2,"Which counts as government purchases (G) in GDP?",["Salaries paid to public school teachers","Paying for a service is a government purchase."],[["Social Security checks","Those are transfer payments."],["Unemployment benefits","Those are transfer payments."],["Interest paid on government bonds","Interest payments are transfers, not purchases of output."]]],
[2,"A Japanese-owned car factory in Ohio produces cars. Those cars count in:",["U.S. GDP","GDP counts production within a country's borders, whoever owns the factory."],[["Japan's GDP","GDP is based on location, not ownership."],["Neither country's GDP","Production in Ohio counts in U.S. GDP."],["Both countries' GDP equally","Each good counts in only one country's GDP."]]],
[2,"Cash payments for unreported work, like off-the-books babysitting, are:",["Not counted in GDP","The underground economy isn't recorded."],[["Counted as consumption","Unreported transactions can't be measured."],["Counted as transfer payments","They aren't transfers."],["Counted only if taxed later","GDP counts recorded market production."]]],
[2,"In the base year, real GDP and nominal GDP are:",["Equal","Base-year prices are the current prices in that year."],[["Real GDP is always larger","They are equal in the base year."],["Nominal GDP is always larger","They are equal in the base year."],["Unrelated","Real GDP uses base-year prices."]]],
[2,"A price index has a value of ___ in its base year.",["100","Every index is set to 100 in its base year."],[["0","An index of 0 would mean nothing costs anything."],["1","Indexes are scaled to 100, not 1."],["It depends on the inflation rate","The base year is always 100."]]],
[2,"A common rule of thumb defines a recession as:",["Real GDP falling for two consecutive quarters","It's a widely used, informal definition."],[["Unemployment above 4%","Recessions are defined by output, not one unemployment level."],["Inflation above 3%","Inflation isn't the defining feature."],["Nominal GDP rising slowly","Nominal GDP can rise even in a recession."]]],
[2,"A country has 250 million adults and a labor force of 160 million. The labor force participation rate is:",["64%","160 ÷ 250 = 64%."],[["36%","That's the share not in the labor force."],["156%","That divides the wrong way."],["90 million","That's the number outside the labor force, not a rate."]]],
[2,"180 million people are employed and 20 million are unemployed. The unemployment rate is:",["10%","20 ÷ (180 + 20) = 10%."],[["11.1%","Divide by the labor force, 200 million, not by the employed."],["20%","That isn't the right ratio."],["9%","That doesn't match the numbers."]]],
[2,"Discouraged workers start looking for jobs again but haven't found one yet. The measured unemployment rate:",["Rises","They re-enter the labor force as unemployed."],[["Falls","More unemployed people raise the rate."],["Stays the same","They now count as unemployed."],["Falls to the natural rate","Re-entry doesn't change the natural rate."]]],
[2,"Full employment means:",["Unemployment equals the natural rate","Some frictional and structural unemployment remains."],[["Unemployment is zero","Frictional and structural unemployment always exist."],["Everyone in the population has a job","Many people aren't in the labor force."],["Cyclical unemployment is high","At full employment cyclical unemployment is zero."]]],
[2,"Auto workers are laid off as car sales collapse during a recession. This is:",["Cyclical unemployment","It's caused by the downturn in the business cycle."],[["Frictional unemployment","They aren't between jobs by choice or searching normally."],["Structural unemployment","Their skills still match the industry; demand fell."],["Part of the natural rate","Cyclical unemployment isn't part of the natural rate."]]],
[2,"Deflation is:",["A sustained decline in the overall price level","Prices on average are falling."],[["A fall in the inflation rate","That's disinflation."],["A decline in real GDP","That's a contraction."],["A fall in the price of one good","Deflation refers to the general price level."]]],
[2,"Cost-push inflation is caused by:",["A decrease in SRAS","Rising costs push prices up as output falls."],[["An increase in AD","That's demand-pull inflation."],["An increase in LRAS","That lowers price pressure."],["A decrease in AD","That lowers prices."]]],
[2,"Demand-pull inflation is caused by:",["An increase in aggregate demand","Spending grows faster than the economy can produce."],[["A decrease in SRAS","That's cost-push inflation."],["An increase in productivity","That reduces inflation pressure."],["A decrease in the money supply","That lowers AD."]]],
[2,"Shoe-leather costs of inflation are:",["The time and effort people spend holding less cash","People make extra trips to the bank to avoid holding money that loses value."],[["The cost of reprinting menus and price tags","Those are menu costs."],["Higher prices for shoes","It's a metaphor, not literal."],["The tax on inflation gains","That's not what the term means."]]],
[2,"A bank lends at a 4% nominal rate, expecting no inflation. Inflation turns out to be 6%. The real interest rate is:",["−2%, so the lender loses","4% − 6% = −2%."],[["10%, so the lender gains","Inflation is subtracted, not added."],["4%, unchanged","The real rate depends on actual inflation."],["2%, so the borrower loses","The sign is reversed, and the borrower gains."]]],
[2,"Unexpected deflation hurts:",["Borrowers","They repay loans with dollars that are worth more than expected."],[["Lenders","Lenders gain from repayment in more valuable dollars."],["Savers holding cash","Cash gains purchasing power in deflation."],["People on fixed incomes","Fixed incomes buy more when prices fall."]]],
[2,"The price of imported cars rises sharply. Which index is affected?",["The CPI, but not the GDP deflator","Imports are in the consumer basket but aren't domestic production."],[["The GDP deflator, but not the CPI","The deflator excludes imports."],["Both equally","Only the CPI includes imported consumer goods."],["Neither","Consumers buy imported cars, so the CPI changes."]]],
[2,"The price of military equipment bought by the government rises. Which index is affected?",["The GDP deflator, but not the CPI","Government purchases are in GDP but not in the consumer basket."],[["The CPI, but not the GDP deflator","Consumers don't buy tanks."],["Both equally","Only the deflator covers government purchases."],["Neither","It's part of domestic output, so the deflator changes."]]],
[2,"Part-time workers who want full-time jobs are counted as:",["Employed, so official unemployment understates labor market weakness","They have some work, so they aren't unemployed."],[["Unemployed","Any paid work counts as employed."],["Not in the labor force","They're working, so they're in the labor force."],["Discouraged workers","Discouraged workers have stopped looking and have no job."]]],

/* ---------- Unit 3 ---------- */
[3,"If the MPC is 0.8, an extra $100 of disposable income raises consumption by:",["$80","Consumption rises by MPC × the change in income."],[["$20","That's the change in saving."],["$100","Part of the income is saved."],["$500","That's the multiplier effect on GDP, not the first-round change in consumption."]]],
[3,"A higher price level raises interest rates, which reduces investment. This explains:",["Why AD slopes downward (the interest-rate effect)","It's a movement along AD."],[["Why AD shifts left","A price-level change moves along AD."],["Why SRAS slopes upward","This is about demand."],["Why LRAS is vertical","LRAS reflects full employment."]]],
[3,"Firms expect higher future profits. Aggregate demand:",["Shifts right because investment rises","Expected profits drive investment spending."],[["Shifts left","Optimism raises investment."],["Doesn't change, but SRAS shifts right","Expected profits mainly affect investment, part of AD."],["Doesn't change","Investment is a component of AD."]]],
[3,"The short-run aggregate supply curve slopes upward mainly because:",["Wages and some prices are sticky in the short run","When output prices rise faster than costs, firms produce more."],[["Of the law of demand","That's about buyers."],["Of the wealth effect","That explains AD."],["Productivity always rises with output","SRAS slopes up because of sticky costs."]]],
[3,"The long-run aggregate supply curve is vertical because:",["In the long run, wages and prices fully adjust","Output returns to the full-employment level whatever the price level."],[["Firms never change output","Output can change in the short run."],["AD never shifts","AD can shift; LRAS still stays vertical."],["Taxes are fixed","LRAS reflects resources and technology."]]],
[3,"AD falls. In the short run:",["Real output falls, the price level falls and unemployment rises","Moving down along SRAS lowers both output and prices."],[["Real output rises and the price level falls","Less spending reduces output."],["The price level rises","Lower demand reduces prices."],["Only the price level changes","Output changes too in the short run."]]],
[3,"An adverse supply shock creates a policy dilemma because:",["Policy that fixes unemployment worsens inflation, and vice versa","Stagflation raises both problems at once."],[["Fiscal policy can't affect AD","Fiscal policy affects AD."],["It shifts LRAS right","An adverse shock shifts SRAS left."],["It lowers inflation","Adverse supply shocks raise inflation."]]],
[3,"The recessionary gap is $300 billion and the MPC is 0.75. The minimum increase in government spending to close it is:",["$75 billion","Multiplier = 1 ÷ 0.25 = 4; $300B ÷ 4 = $75B."],[["$300 billion","That ignores the multiplier."],["$100 billion","That uses the tax multiplier of 3."],["$225 billion","That multiplies by the MPC."]]],
[3,"The recessionary gap is $300 billion and the MPC is 0.75. The minimum tax cut to close it is:",["$100 billion","Tax multiplier = 0.75 ÷ 0.25 = 3; $300B ÷ 3 = $100B."],[["$75 billion","That uses the spending multiplier."],["$300 billion","That ignores the multiplier."],["$900 billion","That multiplies the gap by the tax multiplier instead of dividing."]]],
[3,"If the MPC is 0.6, the spending multiplier is:",["2.5","1 ÷ (1 − 0.6) = 2.5."],[["1.67","That's 1 ÷ MPC."],["0.4","That's the MPS."],["1.5","That's the tax multiplier."]]],
[3,"The MPC is 0.8. Transfer payments rise by $10 billion. Real GDP rises by at most:",["$40 billion","Transfers work like a tax cut: multiplier = 0.8 ÷ 0.2 = 4."],[["$50 billion","That uses the spending multiplier; transfers aren't direct purchases."],["$10 billion","That ignores the multiplier."],["$8 billion","That's only the first round."]]],
[3,"Why might expansionary fiscal policy raise GDP by less than the simple multiplier predicts?",["Rising interest rates crowd out private investment","Government borrowing pushes up rates."],[["The MPC is always 1","An MPC of 1 would make the multiplier infinite."],["Government spending isn't part of AD","G is a component of AD."],["Taxes don't affect consumption","They do, but that isn't the reason."]]],
[3,"At every income level, Americans start buying more imported goods. U.S. aggregate demand:",["Shifts left","Higher imports reduce net exports."],[["Shifts right","Imports are subtracted from AD."],["Doesn't change","Net exports are part of AD."],["SRAS shifts right instead","This is a demand-side change."]]],
[3,"The price of imported raw materials falls. U.S. short-run aggregate supply:",["Shifts right","Lower input costs increase SRAS."],[["Shifts left","Cheaper inputs raise supply."],["Doesn't change","Input prices shift SRAS."],["AD shifts left instead","Input costs affect supply."]]],
[3,"Short-run equilibrium output is to the right of LRAS. The economy has:",["An inflationary gap, with unemployment below the natural rate","Output above potential means an overheated economy."],[["A recessionary gap","That's output to the left of LRAS."],["Full employment","Full employment is at LRAS."],["Unemployment above the natural rate","Output above potential means lower unemployment."]]],
[3,"From an inflationary gap, with no policy, the economy self-corrects as:",["Nominal wages rise, SRAS shifts left, and the price level rises","Output returns to potential at a higher price level."],[["Nominal wages fall and SRAS shifts right","That closes a recessionary gap."],["AD shifts left on its own","Adjustment comes through wages and SRAS."],["LRAS shifts right","Potential output doesn't adjust to the gap."]]],
[3,"Contractionary fiscal policy in the short run will:",["Lower real output and the price level","AD shifts left."],[["Raise real output and lower the price level","Less spending lowers output."],["Raise both output and prices","That's expansionary policy."],["Change only LRAS","Fiscal policy mainly shifts AD."]]],
[3,"A progressive income tax acts as an automatic stabilizer because:",["Tax collections rise faster than income in booms and fall faster in recessions","This damps swings in disposable income and spending."],[["Congress votes on it each year","Automatic stabilizers need no new votes."],["It raises the multiplier","It reduces the multiplier."],["It shifts LRAS","It works through AD."]]],
[3,"During a recession, the government's budget deficit tends to grow automatically because:",["Tax revenue falls and transfer payments rise","Less income means less tax; more people qualify for benefits."],[["Congress always passes new spending","This happens without new laws."],["Interest rates rise","Rates usually fall in recessions."],["Exports increase","Exports don't drive the budget."]]],
[3,"Foreign demand for U.S. goods booms. U.S. aggregate demand:",["Shifts right","Higher exports raise net exports."],[["Shifts left","Exports add to AD."],["Doesn't change","Net exports are part of AD."],["SRAS shifts left instead","This is a demand change."]]],
[3,"A housing market crash sharply lowers household wealth. AD:",["Shifts left","Less wealth reduces consumption."],[["Shifts right","Lower wealth cuts spending."],["Doesn't change","Wealth is a determinant of consumption."],["LRAS shifts left instead","This is a demand-side shock."]]],
[3,"AD and SRAS both shift right. What happens?",["Real output rises; the price level is indeterminate","Both raise output; their price effects conflict."],[["The price level rises; output is indeterminate","Both shifts raise output."],["Both output and the price level fall","Both shifts raise output."],["Nothing changes","Both curves moved."]]],
[3,"Which describes the multiplier effect?",["An initial change in spending causes a larger change in GDP","Each round of spending becomes someone else's income."],[["Banks lend out more than they hold","That's the money multiplier."],["Prices rise by more than wages","That's not the spending multiplier."],["Tax cuts always pay for themselves","That's not what the multiplier says."]]],
[3,"Equilibrium is at full employment. Then AD increases. In the short run:",["Output rises above potential and the price level rises","The economy moves into an inflationary gap."],[["Output falls","More spending raises output in the short run."],["Only the price level rises","Output also rises in the short run."],["LRAS shifts right","AD changes don't shift LRAS."]]],
[3,"A government spending increase of $50 billion is fully offset by a $50 billion tax increase. With an MPC of 0.9, real GDP rises by:",["$50 billion","The balanced-budget multiplier is 1."],[["$0","The tax effect is smaller than the spending effect."],["$500 billion","That ignores the tax increase."],["$450 billion","That uses only the tax multiplier."]]],

/* ---------- Unit 4 ---------- */
[4,"Money solves the barter problem known as:",["The double coincidence of wants","With barter, each trader must want what the other has."],[["The free-rider problem","That's about public goods."],["Opportunity cost","Money doesn't remove opportunity cost."],["Inflation","Barter has nothing to do with inflation."]]],
[4,"U.S. dollars are fiat money, which means they:",["Have value because the government declares them legal tender and people accept them","They aren't backed by a commodity."],[["Are backed by gold","The U.S. left the gold standard."],["Can only be used for taxes","They are used for all transactions."],["Have value from the paper they're printed on","The paper itself is nearly worthless."]]],
[4,"You keep $200 in a drawer to spend next year. Money is serving as a:",["Store of value","It holds purchasing power over time."],[["Medium of exchange","You aren't spending it yet."],["Unit of account","You aren't using it to compare prices."],["Factor of production","Money isn't a factor of production."]]],
[4,"Why does the quantity of money demanded fall when the nominal interest rate rises?",["Interest is the opportunity cost of holding money","Holding cash means giving up interest on bonds."],[["Higher rates raise the price level","That's not the reason."],["The Fed lowers the money supply","That's a supply-side change."],["People need more money for transactions","That would increase money demand."]]],
[4,"A bank has $50,000 in demand deposits and the reserve requirement is 10%. Its required reserves are:",["$5,000","10% × $50,000 = $5,000."],[["$45,000","That's the amount above required reserves."],["$500,000","That multiplies by 10."],["$50,000","That's all deposits."]]],
[4,"A customer deposits $2,000 in cash. The reserve requirement is 20%. The bank's excess reserves rise by:",["$1,600","It must keep $400; the rest is excess."],[["$400","That's the required reserve."],["$2,000","Only part is excess."],["$10,000","That's the multiplier on the deposit."]]],
[4,"The Fed buys $100 million in bonds from banks. The reserve requirement is 10%. The maximum increase in the money supply is:",["$1,000 million","All $100 million becomes excess reserves; × 10 = $1 billion."],[["$100 million","That ignores the multiplier."],["$900 million","With a purchase from banks, the full amount is excess reserves."],["$10 million","That multiplies by the requirement."]]],
[4,"The Fed sells $50 million in bonds. The reserve requirement is 20%. The maximum decrease in the money supply is:",["$250 million","$50M × (1 ÷ 0.2) = $250M."],[["$50 million","That ignores the multiplier."],["$10 million","That multiplies by the requirement."],["$200 million","That subtracts the initial amount."]]],
[4,"The Fed increases the money supply. In the short run, the money market shows:",["A lower nominal interest rate, which raises investment","Cheaper borrowing encourages spending."],[["A higher nominal interest rate","More money lowers rates."],["Higher money demand","The Fed shifts supply, not demand."],["No change in interest rates","The rate falls when MS rises."]]],
[4,"Which asset is the least liquid?",["A house","Selling it takes time and costs money."],[["Currency","Currency is perfectly liquid."],["A checking deposit","It's spendable immediately."],["A savings deposit","It can be moved to checking quickly."]]],
[4,"In the loanable funds market, demand comes from:",["Borrowers, such as firms investing and governments running deficits","They want to borrow funds."],[["Savers","Savers supply funds."],["The Fed only","The Fed doesn't drive loanable funds demand."],["Foreign tourists","Tourists don't borrow in this market."]]],
[4,"The government creates an investment tax credit. In the loanable funds market:",["Demand rises and the real interest rate rises","Firms want to borrow more to invest."],[["Supply rises and the real interest rate falls","The credit affects borrowers, not savers."],["Demand falls","It makes investment more attractive."],["Nothing changes","Investment demand shifts."]]],
[4,"Lenders want a 3% real return and expect 4% inflation. They will charge a nominal rate of about:",["7%","Nominal = real + expected inflation."],[["1%","That subtracts instead of adding."],["3%","That ignores inflation."],["12%","That multiplies instead of adding."]]],
[4,"A bank's owners' equity (capital) equals:",["Assets minus liabilities","It's what would be left for owners if all debts were paid."],[["Deposits plus loans","Deposits are liabilities, loans are assets."],["Reserves minus loans","That isn't equity."],["Required reserves","That's a regulatory requirement, not equity."]]],
[4,"A bank makes a $5,000 loan by crediting the borrower's checking account. The money supply:",["Increases by $5,000","New checkable deposits are new money."],[["Decreases by $5,000","Lending creates deposits."],["Doesn't change","New deposits add to M1."],["Increases by $50,000","That's a system-wide multiplier, not one loan."]]],
[4,"A borrower repays a $5,000 bank loan from her checking account. The money supply:",["Decreases","Repaying a loan destroys deposits."],[["Increases","Repayment removes deposits."],["Doesn't change","Deposits shrink."],["Increases by the interest paid","Interest moves money to the bank; it doesn't create money."]]],
[4,"Which group sets the Federal Reserve's target for the federal funds rate?",["The Federal Open Market Committee (FOMC)","It meets about eight times a year to set policy."],[["Congress","Monetary policy is set by the Fed, not Congress."],["The Treasury Department","The Treasury manages fiscal operations."],["Commercial banks","Banks trade reserves; they don't set the target."]]],
[4,"Large-scale purchases of long-term bonds by a central bank (quantitative easing) aim to:",["Lower long-term interest rates","Buying long-term bonds raises their prices and lowers their yields."],[["Raise long-term interest rates","Purchases push yields down."],["Reduce the money supply","Purchases add reserves."],["Balance the federal budget","That's fiscal policy."]]],
[4,"Expansionary monetary policy may do little if:",["Banks hold extra reserves instead of lending","New reserves don't become loans and spending."],[["Interest rates fall","Falling rates are how it's supposed to work."],["Investment is sensitive to interest rates","That makes it more effective."],["The MPC is high","A high MPC helps policy work."]]],
[4,"Higher interest rates most directly reduce:",["Business investment and spending on big-ticket items like cars and homes","Those purchases are usually financed by borrowing."],[["Government transfer payments","Transfers are set by law."],["The natural rate of unemployment","Rates don't directly change the natural rate."],["Exports in the long run only","The main channel is investment."]]],
[4,"A bond pays $50 a year. If its market price falls from $1,000 to $800, its yield:",["Rises from 5% to 6.25%","50 ÷ 800 = 6.25%."],[["Falls from 5% to 4%","A lower price means a higher yield."],["Stays at 5%","The yield depends on the price."],["Rises to 50%","That isn't the yield."]]],
[4,"Which graph best shows how the Fed changes the nominal interest rate in the short run?",["The money market","Money supply and money demand set the nominal rate."],[["The loanable funds market","That sets the real interest rate."],["The production possibilities curve","It shows production tradeoffs."],["The foreign exchange market","It sets exchange rates."]]],
[4,"The Fed raises the discount rate. Other things equal:",["Banks borrow fewer reserves, and the money supply tends to fall","Borrowing from the Fed becomes more expensive."],[["The money supply rises","A higher rate discourages borrowing."],["The federal funds rate falls","A tighter stance pushes rates up."],["Bond prices rise","Tighter policy lowers bond prices."]]],
[4,"Which is NOT a tool of U.S. monetary policy?",["Changing income tax rates","Tax rates are set by Congress: fiscal policy."],[["Open market operations","That's a Fed tool."],["Interest on reserve balances","That's a Fed tool."],["The discount rate","That's a Fed tool."]]],
[4,"In the money market, an increase in real GDP will:",["Raise money demand and the nominal interest rate","More transactions mean more money is needed."],[["Lower money demand","More output raises money demand."],["Raise the money supply","The Fed controls money supply."],["Lower the nominal interest rate","Higher demand raises the rate."]]],

/* ---------- Unit 5 ---------- */
[5,"The short-run Phillips curve crosses the long-run Phillips curve at:",["The expected inflation rate","At the natural rate, actual inflation equals expected inflation."],[["Zero inflation","Only if expected inflation is zero."],["Zero unemployment","The LRPC is at the natural rate."],["The highest inflation rate","There's nothing special about the highest rate."]]],
[5,"The Fed tightens policy to bring down high inflation. In the short run, this appears as:",["A movement down and to the right along the SRPC","Inflation falls and unemployment rises."],[["A movement up and to the left along the SRPC","That's an AD increase."],["A rightward shift of the LRPC","The natural rate hasn't changed."],["No change in unemployment","Tighter policy raises unemployment in the short run."]]],
[5,"People believe the central bank's promise to lower inflation. The cost of disinflation is likely to be:",["Smaller, because expected inflation and the SRPC adjust faster","Credible policy lowers expectations quickly."],[["Larger, because unemployment must rise more","Credibility reduces the unemployment cost."],["Unchanged","Expectations matter."],["Zero inflation immediately","Adjustment still takes time."]]],
[5,"In the long run, repeated expansionary monetary policy leads to:",["Higher inflation with unemployment back at the natural rate","There's no lasting tradeoff."],[["Permanently lower unemployment","Unemployment returns to the natural rate."],["Lower inflation","More money raises inflation."],["A rightward shift of the LRPC","The natural rate doesn't depend on money."]]],
[5,"Nominal GDP is $20 trillion and the money supply is $5 trillion. Velocity is:",["4","V = nominal GDP ÷ M = 20 ÷ 5."],[["100","That multiplies."],["0.25","That divides the wrong way."],["15","That subtracts."]]],
[5,"The money supply is $2 trillion and velocity is 5. Nominal GDP is:",["$10 trillion","M × V = P × Q = 2 × 5."],[["$2.5 trillion","That divides."],["$7 trillion","That adds."],["$0.4 trillion","That divides the wrong way."]]],
[5,"Velocity is constant, real output grows 3% and the money supply grows 3%. Inflation will be about:",["0%","Money growth just matches output growth."],[["3%","Real output absorbs the new money."],["6%","That adds the two growth rates."],["−3%","Money isn't shrinking."]]],
[5,"Velocity is constant, the money supply grows 8% and real output grows 3%. Inflation will be about:",["5%","8% − 3% = 5%."],[["8%","That ignores output growth."],["11%","That adds them."],["3%","That's the output growth rate."]]],
[5,"A government finances its deficits by printing money instead of borrowing. The most likely long-run result is:",["Higher inflation","The money supply grows faster than output."],[["Lower inflation","More money raises prices."],["Higher real interest rates from crowding out","Printing money avoids borrowing, though it causes inflation."],["Faster long-run growth","Money growth doesn't raise potential output."]]],
[5,"One long-run cost of a large national debt is:",["Higher interest payments that compete with other spending or require higher taxes","Debt has to be serviced."],[["It always causes deflation","There's no such rule."],["It lowers interest rates","Large borrowing tends to raise them."],["It shifts LRAS right","Crowding out tends to slow LRAS growth."]]],
[5,"A new technology lets workers produce more with the same capital. This:",["Raises productivity and shifts LRAS right","Technology is a key source of growth."],[["Shifts AD left","It's a supply-side change."],["Shifts LRAS left","Better technology raises potential output."],["Raises the natural rate of unemployment","Technology raises output, not the natural rate."]]],
[5,"Investment in physical capital today is likely to:",["Raise labor productivity in the future","Workers with more tools produce more."],[["Lower future productivity","More capital raises productivity."],["Have no long-run effect","Capital accumulation drives growth."],["Shift the LRPC right","Capital affects LRAS, not the natural rate directly."]]],
[5,"Policies that discourage saving tend to:",["Reduce investment and slow long-run growth","Less saving means less loanable funds for investment."],[["Speed up long-run growth","Growth depends on investment."],["Lower real interest rates","Less saving raises real interest rates."],["Have no effect on investment","Saving funds investment."]]],
[5,"The best measure of a country's average standard of living is:",["Real GDP per capita","It adjusts for both prices and population."],[["Nominal GDP","It includes price changes and ignores population."],["Total real GDP","It ignores population."],["The unemployment rate","It measures jobs, not living standards."]]],
[5,"Real GDP grows 4% and population grows 1%. Real GDP per capita grows about:",["3%","Per-capita growth ≈ GDP growth − population growth."],[["5%","Population growth is subtracted."],["4%","That ignores population."],["1%","That's population growth."]]],
[5,"Using the rule of 70, if real GDP doubles every 10 years, its growth rate is about:",["7%","70 ÷ 10 = 7."],[["10%","That's the doubling time."],["0.7%","That's off by a factor of 10."],["70%","That's not a yearly rate."]]],
[5,"The labor force grows because of immigration of working-age adults. LRAS:",["Shifts right","More labor raises potential output."],[["Shifts left","More workers increase capacity."],["Doesn't change","The quantity of labor shifts LRAS."],["Only AD shifts","Labor force growth is a supply-side change."]]],
[5,"Supply-side tax cuts that raise incentives to work and invest would shift:",["Both AD and LRAS to the right","They raise spending now and capacity later."],[["Only AD to the left","Tax cuts raise AD."],["Only SRAS to the left","Incentives raise supply."],["LRAS to the left","Better incentives raise potential output."]]],
[5,"Expansionary fiscal policy is combined with contractionary monetary policy. Which is certain?",["Interest rates rise","Both policies push rates up; their effects on output conflict."],[["Real output rises","The two policies push AD in opposite directions."],["Real output falls","The net effect on output is unclear."],["Interest rates fall","Both push rates up."]]],
[5,"Expansionary fiscal policy is combined with expansionary monetary policy. Which is certain?",["AD increases","Both shift AD right; their effects on interest rates conflict."],[["Interest rates rise","Fiscal pushes rates up, monetary pushes them down."],["Interest rates fall","The net rate effect is unclear."],["AD decreases","Both policies raise AD."]]],
[5,"AD decreases. On the Phillips curve, the economy moves:",["Down and to the right along the SRPC","Inflation falls and unemployment rises."],[["Up and to the left along the SRPC","That's an AD increase."],["To a new LRPC","The natural rate doesn't change."],["Along the LRPC","Short-run moves are along the SRPC."]]],
[5,"Adaptive expectations means people form inflation expectations based on:",["Recent past inflation","They extrapolate from experience."],[["Only official forecasts","That's closer to rational expectations."],["The unemployment rate","Expectations are about inflation."],["Nothing; expectations are fixed","Expectations adjust over time."]]],
[5,"The Federal Reserve's stated longer-run inflation goal is:",["2%","The Fed targets 2% inflation over the longer run."],[["0%","The Fed aims for low, positive inflation, not zero."],["5%","That's well above the target."],["Whatever keeps unemployment at zero","The Fed doesn't target zero unemployment."]]],
[5,"Crowding out is larger when:",["Private investment is very sensitive to interest rates","A small rate increase cuts investment a lot."],[["Investment doesn't respond to interest rates","Then there's little crowding out."],["The government runs a surplus","Surpluses lower interest rates."],["The Fed lowers rates at the same time","That offsets crowding out."]]],
[5,"Which would shift the long-run Phillips curve to the right?",["An increase in the natural rate of unemployment","The LRPC is located at the natural rate."],[["An increase in AD","That moves along the SRPC."],["Higher expected inflation","That shifts the SRPC."],["A fall in the money supply","Money doesn't change the natural rate."]]],

/* ---------- Unit 6 ---------- */
[6,"Under a floating exchange rate system, exchange rates are determined by:",["Supply and demand in foreign exchange markets","Prices of currencies adjust like other prices."],[["Government decree","That describes a fixed rate."],["The gold standard","That's an old fixed system."],["The World Bank","It doesn't set exchange rates."]]],
[6,"The euro appreciates against the dollar. U.S. imports from Europe will most likely:",["Fall, because European goods cost more dollars","Each euro now costs more dollars."],[["Rise","European goods became pricier for Americans."],["Not change","Relative prices changed."],["Rise, because the dollar is stronger","The dollar weakened against the euro."]]],
[6,"Foreign demand for U.S. Treasury bonds rises sharply. The dollar:",["Appreciates","Foreigners need dollars to buy the bonds."],[["Depreciates","Demand for dollars rose."],["Doesn't change","Asset demand affects currency demand."],["Depreciates against all currencies","Demand for dollars increased."]]],
[6,"If €1 = $1.25, then $1 equals:",["€0.80","1 ÷ 1.25 = 0.80."],[["€1.25","That's the dollar price of a euro."],["€0.25","That subtracts."],["€2.25","That adds."]]],
[6,"A shirt costs $40 in the U.S. If $1 = 150 yen, the shirt costs a Japanese buyer:",["6,000 yen","40 × 150 = 6,000."],[["3.75 yen","That divides 150 by 40."],["190 yen","That adds."],["0.27 yen","That divides 40 by 150."]]],
[6,"The exchange rate moves from 100 yen per dollar to 120 yen per dollar. The dollar has:",["Appreciated","A dollar now buys more yen."],[["Depreciated","It buys more yen, so it strengthened."],["Stayed the same","The rate changed."],["Appreciated, and so has the yen","If the dollar rises against the yen, the yen falls."]]],
[6,"Large foreign financial capital inflows into the U.S. tend to:",["Increase the supply of loanable funds and lower the real interest rate","Foreign saving adds to funds available to borrow."],[["Raise the real interest rate","More supply lowers the rate."],["Reduce U.S. investment","Cheaper borrowing raises investment."],["Have no effect on interest rates","Inflows add to loanable funds."]]],
[6,"International students pay tuition to U.S. universities. In the U.S. balance of payments, this is:",["An export of services in the current account","Foreigners are buying a U.S. service."],[["A financial account inflow","No asset is purchased."],["An import","Money flows into the U.S. for a U.S. service."],["Not recorded","Service exports are recorded."]]],
[6,"The U.S. dollar appreciates. All else equal, U.S. aggregate demand:",["Decreases","Net exports fall."],[["Increases","A stronger dollar hurts exports."],["Doesn't change","Net exports are part of AD."],["Only SRAS changes","The main effect is on net exports."]]],
[6,"The Japanese government buys U.S. government bonds. In the U.S. balance of payments, this is recorded in the:",["Financial account, as an inflow","A foreign purchase of a U.S. asset."],[["Current account, as an export","Bonds are financial assets."],["Current account, as an import","No goods or services are traded."],["It isn't recorded","Asset purchases are recorded."]]],
[6,"Investors rush to pull money out of a country (capital flight). That country's currency:",["Depreciates","Investors sell the currency to buy foreign assets."],[["Appreciates","Selling a currency lowers its value."],["Doesn't change","Capital flows move exchange rates."],["Appreciates, then stays fixed","Capital flight weakens a currency."]]],
[6,"U.S. incomes rise faster than incomes abroad. All else equal, Americans buy more imports, so the dollar:",["Depreciates, because Americans supply more dollars","Buying imports means trading dollars for foreign currency."],[["Appreciates","More dollars supplied lowers the dollar's value."],["Doesn't change","Import demand moves the exchange rate."],["Appreciates because U.S. GDP is higher","Higher import spending supplies more dollars."]]],
[6,"Who benefits most directly from free trade?",["Consumers, through lower prices and more variety","Imports increase competition and choice."],[["Domestic firms that compete with imports","They face more competition."],["Workers in protected industries","Protection ends for them."],["The government, through tariff revenue","Free trade means no tariffs."]]],
[6,"A country's currency depreciates sharply. A likely short-run effect is:",["Higher prices for imported goods","Each unit of foreign currency costs more."],[["Lower prices for imports","Imports become more expensive."],["Lower exports","A weaker currency raises exports."],["An immediate trade surplus with no price changes","Prices change first."]]],
[6,"The Fed raises interest rates. Through the exchange rate, U.S. net exports:",["Fall, reinforcing the contractionary effect","Higher rates strengthen the dollar."],[["Rise, offsetting the contraction","A stronger dollar reduces net exports."],["Don't change","Interest rates affect the dollar."],["Rise because imports fall","Imports actually rise with a stronger dollar."]]],
[6,"Expansionary fiscal policy raises U.S. real interest rates. Through the exchange rate, this:",["Appreciates the dollar and lowers net exports, partly offsetting the policy","Higher rates attract capital and strengthen the dollar."],[["Depreciates the dollar and raises net exports","Higher rates strengthen the dollar."],["Has no effect on trade","Exchange rates link to trade."],["Raises exports and imports equally","The dollar's appreciation changes the trade balance."]]],
[6,"How is the current account different from the balance of trade?",["The current account also includes investment income and transfers","The trade balance covers only goods and services."],[["They are identical","The current account is broader."],["The balance of trade includes asset purchases","Asset purchases are in the financial account."],["The current account excludes services","Services are included."]]],
[6,"Demand for Mexican pesos rises. The dollar price of a peso:",["Rises","More demand raises the price of pesos."],[["Falls","Higher demand raises the price."],["Doesn't change","Demand moves the price."],["Rises, and the peso depreciates","A higher price means the peso appreciated."]]],
[6,"Mexican investors buy U.S. stocks. In the market for dollars:",["Demand for dollars increases","They need dollars to buy U.S. assets."],[["Supply of dollars increases","Americans supply dollars; Mexicans demand them here."],["Demand for dollars decreases","Their purchases raise demand."],["Nothing changes","Asset purchases affect currency demand."]]],
[6,"Americans buy Mexican government bonds. In the market for dollars:",["The supply of dollars increases and the dollar depreciates","Americans trade dollars for pesos."],[["Demand for dollars increases","Americans are selling dollars."],["The dollar appreciates","More dollars supplied lowers its value."],["Nothing changes","The transaction requires currency exchange."]]],
[6,"The euro weakens against the dollar. A vacation in Europe becomes:",["Cheaper for Americans","Each dollar buys more euros."],[["More expensive for Americans","The dollar is stronger."],["The same price","Exchange rates change the dollar cost."],["Cheaper for Europeans traveling to the U.S.","A weaker euro makes U.S. trips pricier for them."]]],
[6,"Exports are $300 billion and imports are $450 billion. Net exports are:",["−$150 billion, a trade deficit","300 − 450 = −150."],[["+$150 billion, a trade surplus","Imports exceed exports."],["$750 billion","That adds them."],["−$450 billion","That ignores exports."]]],
[6,"The Chinese yuan appreciates against the dollar. U.S. imports from China will most likely:",["Decrease","Chinese goods cost more dollars."],[["Increase","A stronger yuan makes Chinese goods pricier."],["Not change","Relative prices changed."],["Increase because the dollar is stronger","The dollar weakened against the yuan."]]],
[6,"A country with a fixed exchange rate faces pressure for its currency to appreciate. Its central bank can hold the rate by:",["Selling its own currency and buying foreign currency","More supply of its currency offsets the upward pressure."],[["Buying its own currency","That pushes the value up further."],["Raising interest rates","That would attract capital and push the value up."],["Doing nothing","Without action, the currency would appreciate."]]],
[6,"Tourists from Canada spend more money visiting U.S. cities. In the market for U.S. dollars:",["Demand for dollars increases and the dollar appreciates","Tourists buy dollars to spend in the U.S."],[["Supply of dollars increases","Canadians demand dollars."],["The dollar depreciates","Higher demand raises its value."],["Nothing changes","Tourism affects currency demand."]]]
]);
